/**
 * Enrich notion_write_page arguments from prior search steps in a tool chain.
 */

function isWriteTool(toolName) {
  const n = (toolName || '').toLowerCase();
  return n.includes('write') || n.includes('create');
}

function isCreateNew(args) {
  if (!args || typeof args !== 'object') return false;
  const flag = args.create_new;
  if (flag === true || flag === 'true' || flag === 1 || flag === '1') return true;
  const mode = String(args.mode || args.action || '').toLowerCase();
  return mode.includes('create') || mode.includes('new');
}

function parseSearchResultLine(line) {
  const trimmed = (line || '').trim();
  if (!trimmed.startsWith('- ')) return null;
  const body = trimmed.slice(2);
  const urlMatch = body.match(/^(.+?)\s+\((https?:\/\/[^)]+)\)\s*$/);
  if (urlMatch) {
    return { title: urlMatch[1].trim(), url: urlMatch[2].trim() };
  }
  return { title: body.trim(), url: null };
}

function extractPagesFromSearchSummary(summary) {
  if (!summary || typeof summary !== 'string') return [];
  return summary
    .split('\n')
    .map(parseSearchResultLine)
    .filter(Boolean);
}

function pickPageFromPages(pages, pageTitleHint) {
  if (!pages.length) return null;
  if (pageTitleHint) {
    const hint = pageTitleHint.toLowerCase().trim();
    const exact = pages.find((p) => p.title.toLowerCase() === hint);
    if (exact) return exact;
    const partial = pages.find(
      (p) =>
        p.title.toLowerCase().includes(hint) || hint.includes(p.title.toLowerCase()),
    );
    if (partial) return partial;
  }
  if (pages.length === 1) return pages[0];
  return null;
}

function pickPageFromPriorSearch(priorResults, pageTitleHint) {
  const results = priorResults || [];
  for (let i = results.length - 1; i >= 0; i--) {
    const row = results[i];
    if (!row?.ok || !row.toolName) continue;
    const n = row.toolName.toLowerCase();
    if (!n.includes('search') && !n.includes('read') && !n.includes('fetch')) continue;
    const pages = extractPagesFromSearchSummary(row.summary);
    const picked = pickPageFromPages(pages, pageTitleHint);
    if (picked) return picked;
  }
  return null;
}

function enrichWriteArguments(toolName, args, priorResults) {
  const base = { ...(args || {}) };
  if (!isWriteTool(toolName) || isCreateNew(base)) {
    return base;
  }
  if (base.page_id || base.page_url) {
    return base;
  }
  const hint =
    base.page_title || base.target_page || base.title || null;
  const picked = pickPageFromPriorSearch(priorResults, hint);
  if (picked?.url) {
    base.page_url = picked.url;
  }
  if (picked?.title && !base.page_title) {
    base.page_title = picked.title;
  }
  return base;
}


/**
 * Enrich notion_edit_block arguments (page from prior search).
 */

import {
  isCreateNew,
  pickPageFromPriorSearch,
} from './enrich-write-step.core.js';

function isEditTool(toolName) {
  const n = (toolName || '').toLowerCase();
  return n.includes('edit');
}

function enrichEditArguments(toolName, args, priorResults) {
  const base = { ...(args || {}) };
  if (!isEditTool(toolName)) {
    return base;
  }
  if (base.page_id || base.page_url) {
    return base;
  }
  const hint = base.page_title || base.target_page || base.title || null;
  const picked = pickPageFromPriorSearch(priorResults, hint);
  if (picked?.url) {
    base.page_url = picked.url;
  }
  if (picked?.title && !base.page_title) {
    base.page_title = picked.title;
  }
  return base;
}

function enrichToolStepArguments(toolName, args, priorResults) {
  let out = { ...(args || {}) };
  if (!isCreateNew(out)) {
    const hint = out.page_title || out.target_page || out.title || null;
    const picked = pickPageFromPriorSearch(priorResults, hint);
    if (picked?.url && !out.page_url && !out.page_id) {
      out.page_url = picked.url;
    }
    if (picked?.title && !out.page_title) {
      out.page_title = picked.title;
    }
  }
  out = enrichEditArguments(toolName, out, priorResults);
  return out;
}


// Parse webhook body + env for one tool step in a chain.
const env = typeof $env !== 'undefined' ? $env : process.env;
const body = $input.first().json.body || $input.first().json;

const aiBase = env.N8N_AI_BASE_URL || 'http://ai:8083/v1/ai';
const mcpBase = env.N8N_MCP_BASE_URL || 'http://mcp:8081/v1/mcp';
const policyBase = env.N8N_POLICY_BASE_URL || 'http://policy:8085/v1/policy';
const aiKey = env.AI_INTERNAL_API_KEY || 'dev-internal-key';
const policyKey = env.POLICY_INTERNAL_API_KEY || 'dev-internal-key';
const mcpKey = env.MCP_INTERNAL_API_KEY || 'dev-internal-key';

const step = body.step;
const stepIndex = body.stepIndex || 1;
const totalSteps = body.totalSteps || 1;
const priorResults = body.priorResults || [];

const base = {
  orgId: body.orgId,
  workspaceId: body.workspaceId,
  userId: body.userId,
  runId: body.runId,
  stepIndex,
  totalSteps,
  aiBase,
  mcpBase,
  policyBase,
  aiKey,
  policyKey,
  mcpKey,
};

if (!step?.connectorKey || !step?.toolName) {
  return [{ json: { ...base, valid: false, error: 'Invalid tool step payload' } }];
}

const toolArgs = enrichToolStepArguments(step.toolName, step.arguments || {}, priorResults);
return [
  {
    json: {
      ...base,
      valid: true,
      step: {
        connectorKey: step.connectorKey,
        toolName: step.toolName,
        arguments: toolArgs,
      },
      fmtBody: {
        connectorKey: step.connectorKey,
        toolName: step.toolName,
        arguments: toolArgs,
        stepIndex,
        totalSteps,
        workspaceId: body.workspaceId,
      },
    },
  },
];

